for st,s,e in cands:
    sub = seq[s:e] if st=="+" else revcomp(seq[s:e])
    prot = translate(sub)
    prot = prot[:prot.find("*")] if "*" in prot else prot
    print("ORF %s %d-%d: %d aa; start_M=%s ; N-term25=%s"%(st,s+1,e,len(prot),"yes" if prot.startswith("M") else "no",prot[:25]))
